<div className="table-scroll" role="region" tabIndex={0} aria-label="SCP の重要ポイント 表32">{"\n                    "}<table ><thead ><tr className="header"><th scope="col">{"ポイント"}</th><th scope="col">{"内容"}</th></tr></thead><tbody ><tr className="odd"><td >{"権限を付与しない"}</td><td >{"\n                                    SCP は「許可の上限」を決めるだけ。実際の許可は IAM\n                                    ポリシーで与える\n                                "}</td></tr><tr className="even"><td >{"管理アカウントには効かない"}</td><td >{"管理アカウントは SCP の対象外"}</td></tr><tr className="odd"><td >{"継承される"}</td><td >{"上位 OU の SCP は下位に引き継がれる"}</td></tr><tr className="even"><td >{"典型的な用途"}</td><td >{"\n                                    特定リージョン以外の利用禁止、CloudTrail\n                                    の停止禁止、ルートユーザーの利用禁止\n                                "}</td></tr></tbody></table>{"\n                "}</div>
